/**
 * @name Command injection via subprocess
 * @description Detects subprocess calls that may allow command injection
 * @kind path-problem
 * @problem.severity error
 * @id click/command-injection
 * @tags security
 *       external/cwe/cwe-078
 */

import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking
import semmle.python.Concepts
import semmle.python.dataflow.new.RemoteFlowSources
import semmle.python.ApiGraphs

module CommandInjectionConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    // User-controlled input from Click parameters, arguments, options
    exists(DataFlow::CallCfgNode call |
      call = API::moduleImport("click").getMember(["argument", "option", "prompt"]).getACall() and
      source = call
    )
    or
    // Any remote flow source
    source instanceof RemoteFlowSource
  }

  predicate isSink(DataFlow::Node sink) {
    // Subprocess calls with shell=True
    exists(DataFlow::CallCfgNode call |
      call = API::moduleImport("subprocess").getMember(["call", "run", "Popen", "check_call", "check_output"]).getACall() and
      sink = call.getArg(_) and
      call.getArgByName("shell").asExpr().(BooleanLiteral).booleanValue() = true
    )
    or
    // os.system calls
    sink = API::moduleImport("os").getMember("system").getACall().getArg(0)
    or
    // os.popen calls
    sink = API::moduleImport("os").getMember("popen").getACall().getArg(0)
  }
}

module CommandInjectionFlow = TaintTracking::Global<CommandInjectionConfig>;
import CommandInjectionFlow::PathGraph

from CommandInjectionFlow::PathNode source, CommandInjectionFlow::PathNode sink
where CommandInjectionFlow::flowPath(source, sink)
select sink.getNode(), source, sink, "Potential command injection from user input $@.", source.getNode(), "user input"

/**
 * @name Code execution from user input
 * @description Detects potential code execution vulnerabilities
 * @kind path-problem
 * @problem.severity error
 * @id py/click-code-execution
 * @tags security
 */

import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking
import semmle.python.Concepts

module CodeExecConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    exists(DataFlow::ParameterNode param |
      source = param
    )
  }

  predicate isSink(DataFlow::Node sink) {
    sink = any(CodeExecution ce).getCode()
  }
}

module CodeExecFlow = TaintTracking::Global<CodeExecConfig>;
import CodeExecFlow::PathGraph

from CodeExecFlow::PathNode source, CodeExecFlow::PathNode sink
where CodeExecFlow::flowPath(source, sink)
select sink.getNode(), source, sink, "Potential code execution from $@.", source.getNode(), "user input"

