/**
 * @name Regular expression denial of service
 * @description Detects potentially vulnerable regex patterns
 * @kind problem
 * @problem.severity warning
 * @id py/click-redos
 * @tags security
 */

import python
import semmle.python.Concepts
import semmle.python.dataflow.new.DataFlow
import semmle.python.ApiGraphs

/**
 * Holds if the regex pattern contains potentially vulnerable patterns
 * that could lead to catastrophic backtracking.
 */
predicate isVulnerablePattern(DataFlow::Node patternNode) {
  exists(string pattern |
    pattern = patternNode.asExpr().(StringLiteral).getText() and
    (
      // Nested quantifiers: (a+)+ or (a*)*
      pattern.regexpMatch(".*\\([^)]*[+*][^)]*\\)[+*].*") or
      // Overlapping alternatives with quantifiers: (a|a)+ or (ab|a)+
      pattern.regexpMatch(".*\\([^)|]+\\|[^)]+\\)[+*].*") or
      // Repeated groups with wildcards: (.*)+
      pattern.regexpMatch(".*\\(\\.\\*\\)[+*].*") or
      // Multiple consecutive quantifiers on character classes
      pattern.regexpMatch(".*\\[[^]]+\\][+*]\\s*\\[[^]]+\\][+*].*")
    )
  )
}

from DataFlow::CallCfgNode call, DataFlow::Node patternArg, string pattern
where
  (
    // re.compile() calls
    call = API::moduleImport("re").getMember("compile").getACall() or
    // re.match() calls
    call = API::moduleImport("re").getMember("match").getACall() or
    // re.search() calls
    call = API::moduleImport("re").getMember("search").getACall() or
    // re.findall() calls
    call = API::moduleImport("re").getMember("findall").getACall() or
    // re.finditer() calls
    call = API::moduleImport("re").getMember("finditer").getACall() or
    // re.fullmatch() calls
    call = API::moduleImport("re").getMember("fullmatch").getACall() or
    // re.sub() calls
    call = API::moduleImport("re").getMember("sub").getACall() or
    // re.subn() calls
    call = API::moduleImport("re").getMember("subn").getACall()
  ) and
  patternArg = call.getArg(0) and
  isVulnerablePattern(patternArg) and
  pattern = patternArg.asExpr().(StringLiteral).getText()
select call, "Potentially vulnerable regular expression pattern that may cause ReDoS: " + pattern

/**
 * @name Server-Side Request Forgery (SSRF)
 * @description Detects user input flowing to HTTP requests
 * @kind path-problem
 * @problem.severity error
 * @id py/click-ssrf
 * @tags security
 */

import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking
import semmle.python.ApiGraphs

module SSRFConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    exists(DataFlow::ParameterNode param |
      source = param
    )
  }

  predicate isSink(DataFlow::Node sink) {
    exists(DataFlow::CallCfgNode call |
      (
        call = API::moduleImport("urllib").getMember("request").getMember("urlopen").getACall() or
        call = API::moduleImport("urllib").getMember("request").getMember("Request").getACall() or
        call = API::moduleImport("requests").getMember("get").getACall() or
        call = API::moduleImport("requests").getMember("post").getACall() or
        call = API::moduleImport("requests").getMember("request").getACall()
      ) and
      sink = call.getArg(0)
    )
  }
}

module SSRFFlow = TaintTracking::Global<SSRFConfig>;
import SSRFFlow::PathGraph

from SSRFFlow::PathNode source, SSRFFlow::PathNode sink
where SSRFFlow::flowPath(source, sink)
select sink.getNode(), source, sink, "Potential SSRF from $@.", source.getNode(), "user input"
